-- (a) category rules for brand profiles
update phg_mix.ingredient_profiles set sugar_g_100ml = 0, ta_g_100ml = 0, updated_at = now(),
  notes = replace(coalesce(notes,''), 'Resolve sugar: product-specific (only a legal bound or ABV is sourced). ', '') || ' Sugar/TA = 0 by category rule: bourbon may contain no coloring, flavoring or blending materials (27 CFR 5.143).'
