  notes = replace(coalesce(notes,''), 'Resolve sugar: product-specific (only a legal bound or ABV is sourced). ', '') || ' Sugar/TA modeled 0 within the US vodka bound (<=2 g/L sugar, <=1 g/L citric acid; 27 CFR 5.142).'
 where key in ('ip_belvedere_vodka_us','ip_haku_vodka_us') and sugar_g_100ml is null;
update phg_mix.ingredient_profiles set sugar_g_100ml = 0, ta_g_100ml = 0, updated_at = now(),
  sugar_profile = sugar_profile || '{"abocado_additives_max_pct_by_weight":1}'::jsonb,
  notes = replace(coalesce(notes,''), 'Resolve sugar: product-specific (only a legal bound or ABV is sourced). ', '') || ' Sugar modeled 0 (working model) within NOM-006 s.4.1 bound: mellowing additives <=1% of weight.'
 where key in ('ip_patron_silver_us','ip_patron_reposado_us','ip_el_tesoro_blanco_us','ip_el_tesoro_reposado_us',
               'ip_espolon_reposado_us','ip_milagro_silver_us','ip_ocho_plata_us') and sugar_g_100ml is null;
