insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_rum_generic_eu', 'Rum - Product Unspecified (EU category 1 bound)', 'spirit', null, 'rum', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 20, "rule": "EU 2019/787 Annex I cat. 1(f): <=20 g sweetening products/L as invert sugar"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 1 (Rum), points (b) and (f) - "The minimum alcoholic strength by volume of rum shall be 37,5 %. ... Rum may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar."', 'high', 'official', 'Regulatory upper bound only (0-20 g/L invert-sugar equivalent = 0-2.0 g/100 mL); actual sugar product-specific and often ~0. Binds only rum sold as ''rum'' in the EU/UK; US-market rum is not bound by this rule. ABV product-specific (EU minimum 37.5%). Caramel allowed only for colour; rum shall not be flavoured, so spiced rum is outside this category.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_rum_generic_eu', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 1 (Rum), points (b) and (f)', 'primary', 'The minimum alcoholic strength by volume of rum shall be 37,5 %. ... Rum may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar.') on conflict do nothing;
