insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_whisky_generic_eu', 'Whisky/Whiskey - Product Unspecified (EU category 2)', 'spirit', null, 'whisky', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 0, "rule": "EU 2019/787 Annex I cat. 2(d): shall not be sweetened; only plain caramel E150a"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 2 (Whisky or whiskey), points (a), (b), (d) - "The final distillate, to which only water and plain caramel (for colouring) may be added ... The minimum alcoholic strength by volume of whisky or whiskey shall be 40 %. ... Whisky or whiskey shall not be sweetened, even for rounding off the taste, or flavoured, or contain any additives other than plain caramel (E 150a) used for adjusting the colour."', 'high', 'official', 'No sweetening permitted: sugar bound 0 g/L (E150a caramel only, a colouring amount). Applies to Irish whiskey (EU GI in this category) and any whisky marketed in the EU. US bourbon/rye have their own profiles (ip_bourbon_generic etc.). ABV product-specific (min 40%).') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_whisky_generic_eu', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 2 (Whisky or whiskey), points (a), (b), (d)', 'primary', 'The final distillate, to which only water and plain caramel (for colouring) may be added ... The minimum alcoholic strength by volume of whisky or whiskey shall be 40 %. ... Whisky or whiskey shall not be sweetened, even for rounding off the taste, or flavoured, or contain any additives other than p') on conflict do nothing;
