insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_scotch_whisky_generic', 'Scotch Whisky - Product Unspecified (Scotch Whisky Regulations 2009)', 'spirit', null, 'scotch whisky', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 0, "rule": "Scotch Whisky Regulations 2009 reg. 3(1)(h): only water and plain caramel colouring may be added"}}'::jsonb, '{}'::jsonb, '{"abv_market": "UK (legal minimum, not a product value)"}'::jsonb, 'UK Government (legislation.gov.uk): reg. 3(1)(h) and (i), latest revised version - "(h)to which no substance has been added, or to which no substance has been added except— (i)water; (ii)plain caramel colouring; or (iii)water and plain caramel colouring; and (i)that has a minimum alcoholic strength by volume of 40%."', 'high', 'official', 'Only water and plain caramel may be added: sugar bound 0 g/L. ABV product-specific (legal minimum 40%).') on conflict (key) do nothing;
