insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_wine_spirit_generic_eu', 'Wine Spirit - Product Unspecified (EU category 4)', 'spirit', null, 'wine spirit', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 20, "rule": "EU 2019/787 Annex I cat. 4(f): <=20 g/L as invert sugar"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 4 (Wine spirit), points (b) and (f) - "The minimum alcoholic strength by volume of wine spirit shall be 37,5 %. ... Wine spirit may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar."', 'high', 'official', 'Upper bound only (<=2.0 g/100 mL). Parent category for Cognac-type grape spirits; see ip_cognac_generic for the mapping caveat. ABV product-specific.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_wine_spirit_generic_eu', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 4 (Wine spirit), points (b) and (f)', 'primary', 'The minimum alcoholic strength by volume of wine spirit shall be 37,5 %. ... Wine spirit may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar.') on conflict do nothing;
insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'site', null, 3, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_cognac_generic', 'Cognac - Product Unspecified (bound via EU wine-spirit category)', 'spirit', null, 'cognac', 'working_model', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 20, "rule": "EU 2019/787 Annex I cat. 4(f) (assumed applicable category for Cognac; unverified)"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 4 (Wine spirit), point (f) - "Wine spirit may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar."', 'low', 'derived', 'WORKING MODEL. The quote is the category-4 rule; that Cognac is registered as a wine-spirit GI was NOT verified from a scraped page this run (Cognac cahier des charges not fetched), and the AOC spec may be stricter. Treat 20 g/L as a provisional upper bound. ABV product-specific (e.g. ip_hennessy_vs_us).') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_cognac_generic', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 4 (Wine spirit), point (f)', 'primary', 'Wine spirit may be sweetened in order to round off the final taste. However, the final product may not contain more than 20 grams of sweetening products per litre, expressed as invert sugar.') on conflict do nothing;
