insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_brandy_generic_eu', 'Brandy/Weinbrand - Product Unspecified (EU category 5)', 'spirit', null, 'brandy', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 35, "rule": "EU 2019/787 Annex I cat. 5(f): <=35 g/L as invert sugar"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 5 (Brandy or Weinbrand), points (b) and (f) - "The minimum alcoholic strength by volume of brandy or Weinbrand shall be 36 %. ... Brandy or Weinbrand may be sweetened in order to round off the final taste. However, the final product may not contain more than 35 grams of sweetening products per litre, expressed as invert sugar."', 'high', 'official', 'Upper bound only (<=3.5 g/100 mL). Binds EU-market ''brandy''; US brandy is governed by 27 CFR 5.145 (not fetched). Excludes pisco (not an EU category). ABV product-specific (min 36%).') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_brandy_generic_eu', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 5 (Brandy or Weinbrand), points (b) and (f)', 'primary', 'The minimum alcoholic strength by volume of brandy or Weinbrand shall be 36 %. ... Brandy or Weinbrand may be sweetened in order to round off the final taste. However, the final product may not contain more than 35 grams of sweetening products per litre, expressed as invert sugar.') on conflict do nothing;
