insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_vodka_generic_eu', 'Vodka - Product Unspecified (EU category 15 bound)', 'spirit', null, 'vodka', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 8, "rule": "EU 2019/787 Annex I cat. 15(e): <=8 g/L as invert sugar"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 15 (Vodka), points (b) and (e) - "The minimum alcoholic strength by volume of vodka shall be 37,5 %. ... Vodka may be sweetened in order to round off the final taste. However, the final product may not contain more than 8 grams of sweetening products per litre, expressed as invert sugar."', 'high', 'official', 'Supplements existing ip_vodka_generic (US 27 CFR 5.142, <=2 g/L). EU bound is looser (<=0.8 g/100 mL). No aliases: generic ''vodka'' stays on ip_vodka_generic.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_vodka_generic_eu', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 15 (Vodka), points (b) and (e)', 'primary', 'The minimum alcoholic strength by volume of vodka shall be 37,5 %. ... Vodka may be sweetened in order to round off the final taste. However, the final product may not contain more than 8 grams of sweetening products per litre, expressed as invert sugar.') on conflict do nothing;
insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_flavoured_vodka_generic', 'Flavoured Vodka - Product Unspecified (EU category 31)', 'spirit', null, 'flavoured vodka', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 100, "rule": "EU 2019/787 Annex I cat. 31(d): <100 g/L as invert sugar when sweetened"}}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 31 (Flavoured vodka), points (b)-(d) - "The minimum alcoholic strength by volume of flavoured vodka shall be 37,5 %. (c) Flavoured vodka may be sweetened, blended, flavoured, matured or coloured. (d) When flavoured vodka is sweetened, the final product shall contain less than 100 grams of sweetening products per litre, expressed as invert sugar."', 'medium', 'official', 'Wide bound: 0 to <10 g/100 mL. Real products range from unsweetened (e.g. Absolut Citron per OHLQ copy) to liqueur-adjacent; product must be named for a usable sugar value. House infusions (apricot-infused vodka) are not mapped here.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_flavoured_vodka_generic', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 31 (Flavoured vodka), points (b)-(d)', 'primary', 'The minimum alcoholic strength by volume of flavoured vodka shall be 37,5 %. (c) Flavoured vodka may be sweetened, blended, flavoured, matured or coloured. (d) When flavoured vodka is sweetened, the final product shall contain less than 100 grams of sweetening products per litre, expressed as invert') on conflict do nothing;
