insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_legislation_gov_uk_d0f2fe', 'Regulation (EU) 2019/787 on spirit drinks, Annex I (Categories of spirit drinks)', 'publication', null, 1, 'European Parliament and Council (via legislation.gov.uk)', null, 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_old_tom_gin_generic', 'Old Tom Gin - Product Unspecified (sweetened gin, no legal cap)', 'spirit', null, 'old tom gin', 'working_model', null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb, '{"abv_market": "EU (legal minimum, not a product value)"}'::jsonb, 'European Parliament and Council (via legislation.gov.uk): Annex I, category 20 (Gin), points (b) and (d) - "The minimum alcoholic strength by volume of gin shall be 37,5 %. ... The term ''gin'' may be supplemented by the term ''dry'' if it does not contain added sweetening exceeding 0,1 grams of sweetening products per litre of the final product, expressed as invert sugar."', 'medium', 'official', 'WORKING MODEL. EU gin (cat. 20) sets no maximum sweetening for a gin not labelled ''dry''; the only limit is the 0.1 g/L threshold to use ''dry''. So Old Tom sugar is unbounded by law and UNRESOLVED until a product''s sugar is published. sugar_bound left null deliberately. Brand example: ip_haymans_old_tom_gin_us (ABV only).') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_old_tom_gin_generic', 'src_legislation_gov_uk_d0f2fe', 'https://www.legislation.gov.uk/eur/2019/787/annex/I/adopted?view=plain', 'Annex I, category 20 (Gin), points (b) and (d)', 'primary', 'The minimum alcoholic strength by volume of gin shall be 37,5 %. ... The term ''gin'' may be supplemented by the term ''dry'' if it does not contain added sweetening exceeding 0,1 grams of sweetening products per litre of the final product, expressed as invert sugar.') on conflict do nothing;
