insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_planalto_gov_br_290e3f', 'Decreto nº 6.871, de 4 de junho de 2009', 'publication', null, 1, 'Presidência da República (planalto.gov.br)', null, 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/decreto/d6871.htm', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_cachaca_generic', 'Cachaça - Product Unspecified (Brazil)', 'spirit', null, 'cachaça', 'generic', null, null, null, null, null, null, null, null, '{"bound": {"max_g_l": 6, "rule": "Decreto 6.871/2009 (cachaça definition): açúcares até 6 g/L; 6-30 g/L = ''cachaça adoçada''. Decree since revoked by Decreto 12.709/2025"}}'::jsonb, '{}'::jsonb, '{"abv_market": "Brazil (legal range 38-48% vol at 20 C, not a product value)"}'::jsonb, 'Presidência da República (planalto.gov.br): cachaça definition and §1 (cachaça adoçada); page header ''Revogado pelo Decreto nº 12.709, de 2025'' - "Cachaça é a denominação típica e exclusiva da aguardente de cana produzida no Brasil, com graduação alcoólica de trinta e oito a quarenta e oito por cento em volume, a vinte graus Celsius, obtida pela destilação do mosto fermentado do caldo de cana-de-açúcar com características sensoriais peculiares, podendo ser adicionada de açúcares até seis gramas por litro. § 1 o A cachaça que contiver açúcare"', 'medium', 'official', 'Bound <=0.6 g/100 mL for unsweetened cachaça. CAVEAT: the planalto page marks Decreto 6.871 as revoked by Decreto 12.709/2025. The current decree (https://www.planalto.gov.br/ccivil_03/_Ato2023-2026/2025/Decreto/D12709.htm, scraped) keeps the 38-48% vol definition (''Cachaça é a denominação típica e exclusiva da aguardente de cana produzida na República Federativa do Brasil, com graduação alcoólica de 38% (trinta e oito por cento) a 48% (quarenta e oito por cento) em volume, a 20 °C (vinte graus Celsius), com características sensoriais peculiares.'') but the extracted text did not state the sugar limit; it may now sit in a MAPA ordinance. Treat 6 g/L as the historical/likely-current rule, not re-verified.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_cachaca_generic', 'src_planalto_gov_br_290e3f', 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/decreto/d6871.htm', 'cachaça definition and §1 (cachaça adoçada); page header ''Revogado pelo Decreto nº 12.709, de 2025''', 'primary', 'Cachaça é a denominação típica e exclusiva da aguardente de cana produzida no Brasil, com graduação alcoólica de trinta e oito a quarenta e oito por cento em volume, a vinte graus Celsius, obtida pela destilação do mosto fermentado do caldo de cana-de-açúcar com características sensoriais peculiares') on conflict do nothing;
