insert into phg_mix.sources (key, title, kind, source_kind, tier, publisher, year, url, access, focus) values ('src_dof_gob_mx_bbbb6d', 'NORMA Oficial Mexicana NOM-070-SCFI-2016, Bebidas alcohólicas-Mezcal-Especificaciones', 'publication', null, 1, 'Diario Oficial de la Federación (dof.gob.mx)', null, 'https://dof.gob.mx/normasOficiales/6437/seeco11_C/seeco11_C.html', 'open', '{formulation}') on conflict (key) do nothing;
insert into phg_mix.ingredient_profiles (key, name, ingredient_class, brand, generic_name, basis, density_g_ml, abv_pct, sugar_g_100ml, sugar_g_100g, ta_g_100ml, ta_min_g_100ml, ta_max_g_100ml, ph, sugar_profile, acid_profile, variability, measurement_basis, confidence, verification, notes) values ('ip_mezcal_generic', 'Mezcal - Product Unspecified (NOM-070)', 'spirit', null, 'mezcal', 'generic', null, null, null, null, null, null, null, null, '{}'::jsonb, '{}'::jsonb, '{"abv_market": "Mexico / certified mezcal (legal range 35-55% vol at 20 C, not a product value)"}'::jsonb, 'Diario Oficial de la Federación (dof.gob.mx): Tabla 2 (Especificaciones fisicoquímicas); categoría e) Abocado con - "TABLA 2-Especificaciones fisicoquímicas | Alcohol Volumen a 20 °C | % Alc. Vol. | 35 | 55 | ... e)Abocado con: Mezcal al que se debe incorporar directamente ingredientes para adicionar sabores, tales como gusano de maguey, damiana, limón, miel, naranja, mango, entre otros ... Únicamente para el caso de Mezcal Abocado Con, se permite un máximo de 60 g/L conforme a la NMX-V-017-NORMEX-2014 (ver 2.7)"', 'high', 'official', 'ABV range 35-55% only; product ABV needed for math. No sugar limit was quoted for plain mezcal; the 60 g/L figure is total dry extract (not sugar) and applies only to ''Mezcal Abocado con'' (flavoured). sugar_bound left null. Plain mezcal is expected to be ~0 sugar but that is not a published bound here.') on conflict (key) do nothing;
insert into phg_mix.formulation_evidence (record_type, record_key, source_key, url, locator, evidence_role, note) values ('ingredient_profile', 'ip_mezcal_generic', 'src_dof_gob_mx_bbbb6d', 'https://dof.gob.mx/normasOficiales/6437/seeco11_C/seeco11_C.html', 'Tabla 2 (Especificaciones fisicoquímicas); categoría e) Abocado con', 'primary', 'TABLA 2-Especificaciones fisicoquímicas | Alcohol Volumen a 20 °C | % Alc. Vol. | 35 | 55 | ... e)Abocado con: Mezcal al que se debe incorporar directamente ingredientes para adicionar sabores, tales como gusano de maguey, damiana, limón, miel, naranja, mango, entre otros ... Únicamente para el caso') on conflict do nothing;
